
require('./backend/node_modules/dotenv').config({path:'backend/.env',quiet:true});
const mongoose=require('./backend/node_modules/mongoose');mongoose.set('autoIndex',false);
const {buildMongoUri,mongoConfig}=require('./backend/src/config/mongoConfig');
(async()=>{let config=mongoConfig();await mongoose.connect(buildMongoUri(),{dbName:config.dbName,authSource:config.authSource,serverSelectionTimeoutMS:10000,autoIndex:false});
const Lead=require('./backend/src/models/Lead');const User=require('./backend/src/models/User');
const original=require('./backend/src/services/leadOwnershipAndEmailWorkflow');
try{Lead.countDocuments(original.noOwnerWorkspaceFilter()).cast(Lead);console.log('before_cast_ok');}catch(error){console.log('before',error.name,error.path,error.kind);}
const Module=require('module'),path=require('path');
function patched(file,encoded){const filename=path.resolve(file);const m=new Module(filename,module);m.filename=filename;m.paths=Module._nodeModulePaths(path.dirname(filename));require.cache[filename]=m;m._compile(Buffer.from(encoded,'base64').toString('utf8'),filename);return m.exports;}
patched('backend/src/services/leadOwnershipAndEmailWorkflow.js','');
const ctrl=patched('backend/src/controllers/leadController.js','');
const user=await User.findOne({isActive:true,role:{$nin:['admin','superadmin']}}).select('_id crmUserId name email role roles teamId managerId operationHeadId').lean();
for(const search of ['', 'el', 'elkay']){let at=Date.now();const headers={};let status=200;let body;await ctrl.listLeads({user,query:{paginated:'true',directory:'true',page:'1',limit:'10',workspace:'leads',search}},{set(k,v){headers[k]=v;return this;},status(v){status=v;return this;},json(v){body=v;}});console.log('patched_read',JSON.stringify({search,status,ms:Date.now()-at,rows:body?.leads?.length,total:body?.pagination?.total,timing:headers['Server-Timing'],error:body?.error}));}
await mongoose.disconnect();})().catch(e=>{console.error('diagnostic_error',e.name,e.code,String(e.message).slice(0,150));process.exitCode=1;});
